// tests/golden/AppearanceCases -- the DECLARATIVE SPEC of the appearance baselines: each case a small page and the
// annotations on it, drawn by our builder. Stage 6 T8, decision D6-6 (`Stage6-Annotations-Plan.md` §3), guide cases
// A-64 and A-65 (`Stage6-Annotations-Testing-Guide.md` §5.11).
//
// ===========================================================================================
// WHY A SPEC IN CODE AND NOT CORPUS FILES
// ===========================================================================================
// The corpus is ours and generated by Python (D2-11); an appearance is OUR BUILDER's output, so a fixture holding it
// would be the product's bytes committed as data -- and regenerated by the very code it is meant to judge. So the
// spec is here, reviewed like `golden/manifest.json` is: a case is a page 200 by 150 points (with a grey band and
// a black bar of page content, so a blend has something to blend with), maybe turned, and its annotations, each
// with a FIXED identity and instant so the bytes are the same every run. `appearancePdf` writes the page with
// each annotation's dictionary exactly as `pdf/ops/AnnotationOps::createdDictionary` writes it and its form
// exactly as `AppearanceStreamBuilder::normal` builds it -- and, for `tests/render/tst_appearance`'s control,
// the same dictionary WITHOUT `/AP`, which PDFium then generates its own appearance for (A-65).
//
// The baselines are `golden/appearance/<name>.png` at `kAppearanceDpi`, captured by
// `golden-update --appearance --reason "…"` and compared by `render.golden.appearance.*` with the corpus
// suite's thresholds. **What a green run claims is the suite's usual and no more**: our builder's streams
// rasterize on THIS rasterizer the way they did when each baseline was LOOKED AT and kept -- not that any other
// reader draws them so (that is M-02's), and not that they are right (that is what looking was for).
//
// Compiled into `rawpage_golden_tests`, `golden-update` and `rawpage_render_tests` alike, so the three read one
// spec.

#ifndef RAWPAGE_TESTS_GOLDEN_APPEARANCECASES_H
#define RAWPAGE_TESTS_GOLDEN_APPEARANCECASES_H

#include "core/doc/Annotation.h"

#include <QString>

#include <string>
#include <vector>

namespace rawpage::golden {

inline constexpr int kAppearanceDpi = 144;
inline constexpr double kAppearancePageWidth = 200.0;
inline constexpr double kAppearancePageHeight = 150.0;

struct AppearanceCase {
    QString name;                              // `appearance/<name>.png`
    QString note;                              // what it shows
    int rotate = 0;                            // the page's /Rotate
    std::vector<core::Annotation> annotations; // fixed identities and instants
};

// Every case, in the order they are captured and listed.
const std::vector<AppearanceCase>& appearanceCases();

// The case's page with its annotations: with our appearance, or -- `withAppearance` false -- with none, so a
// reader generates its own.
std::string appearancePdf(const std::vector<core::Annotation>& annotations, int rotate, bool withAppearance);

// `appearance/<name>.png`, golden-relative.
QString appearanceBaselinePath(const AppearanceCase& item);

} // namespace rawpage::golden

#endif // RAWPAGE_TESTS_GOLDEN_APPEARANCECASES_H
